Translate("deDE", "eastern-plaguelands", {
	title = "Östliche Pestländer",
	aliases = { "Östliche Pest" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Östlichen Pestländer sind das tote Herz dessen, was einst {link:lordaeron}Lordaeron{/link} war. Hier fiel die Seuche des Untodes zuerst und am schwersten, und hier hat sie sich nie gehoben. Die Wälder sind grau und von Fäulnis behangen. Die Flüsse fließen träge und faulig. Die Höfe und Weiler, die einst die große Stadt {red:stratholme}Stratholme{/red} ernährten, sind leer oder schlimmer als leer, denn ihre Bewohner wandeln noch immer im Dienst der {link:scourge}Geißel{/link} über die Straßen. Kein König herrscht über diese Lande. Die Geißel hält sie, der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} macht sie ihr von der Festung {link:tyr-s-hand}Tyrs Hand{/link} aus streitig, und eine kleine Schar der {link:argent-dawn}Argentumdämmerung{/link} hält an der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} im äußersten Osten eine einzige Lampe am Brennen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Vor der Seuche waren die östlichen Marken Lordaerons reiches und ruhiges Land. Stratholme war die zweite Stadt des Königreichs, und um sie herum lagen Gehöfte, Mühlen und Dörfer wie {link:darrowshire}Darrowshire{/link}, {link:northdale}Northdale{/link} und {link:corin-s-crossing}Corins Kreuzung{/link}. {link:tyr-s-hand}Tyrs Hand{/link} bewachte die südöstliche Küste. Im Norden, jenseits des {link:thondroril-river}Thondroril{/link} und der Wälder, unterhielt das Reich {link:quel-thalas}Quel'Thalas{/link} seine Grenzhütten, und die {link:high-elves}Hochelfen{/link}, die dort jagten, waren Nachbarn und Freunde. Keine Chronik verzeichnet, wann das erste dieser Dörfer gegründet wurde. Geschrieben steht, wie sie endeten.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Das Land ist ein Schlachtfeld ohne Front. Der {link:cult-of-the-damned}Kult der Verdammten{/link} errichtet seine finsteren Tempel in {link:corin-s-crossing}Corins Kreuzung{/link} und im Pestwald, wo die {link:scourge}Geißel{/link} neue Diener baut und zusammennäht. Seuchenfledermäuse verdunkeln den Himmel, Seuchenhunde jagen auf den Straßen, und die Aasmaden mästen sich an den Toten. Der Scharlachrote Kreuzzug hält {link:tyr-s-hand}Tyrs Hand{/link} und schickt seine Patrouillen nach Norden in Richtung Stratholme, wobei er alle tötet, die nicht seine Farben tragen. Gegen all dies steht die {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}, wo {link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link} und die {link:argent-dawn}Argentumdämmerung{/link} jeden Verbündeten aufnehmen, lebend oder tot, der gegen die Geißel kämpfen will. Die {link:forsaken}Verlassenen{/link} haben hier ihren eigenen Streiter. {link:nathanos-blightcaller}Nathanos Blightcaller{/link} hält {link:the-marris-stead}Marris' Siedlung{/link} im Südwesten und jagt sowohl die Geißel als auch die Lebenden. Und in einer Hütte am westlichen Fluss lebt ein alter Mann, der einst ein Paladin der Silbernen Hand war: {link:tirion-fordring}Tirion Fordring{/link}.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:scourge}Geißel{/link}.{/b} Ghule, Monstrositäten, Gargoyles und die auferstandenen Toten der östlichen Dörfer füllen das Land. Sie dienen dem Lichkönig durch die Nekromanten des Kults der Verdammten.
• {b}Der Scharlachrote Kreuzzug.{/b} Seine Ritter und Kleriker halten {link:tyr-s-hand}Tyrs Hand{/link} und die Scharlachrote Basilika. Sie führen Krieg gegen die Geißel und gegen alle anderen.
• {b}Die {link:argent-dawn}Argentumdämmerung{/link}.{/b} Von der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} aus führen ihre Ritter, Gelehrten und Rüstmeister einen geduldigen Krieg gegen die Untoten, und sie belohnen jeden, der ihnen die Beweise des Kampfes bringt.
• {b}Die Verlassenen.{/b} {link:nathanos-blightcaller}Nathanos Blightcaller{/link}, der Streiter der Bansheekönigin, führt von {link:the-marris-stead}Marris' Siedlung{/link} aus seinen eigenen Krieg.
• {b}Die {link:high-elves}Hochelfen{/link} von {link:quel-lithien-lodge}Quel'Lithien{/link}.{/b} In einer Hütte an der nördlichen Grenze halten Waldläufer aus {link:quel-thalas}Quel'Thalas{/link} noch immer Wache.
• {b}Die Trolle der Mossflayer.{/b} Von der zerstörten Stadt {link:zul-mashar}Zul'Mashar{/link} aus kämpft ein Stamm von {link:trolls}Waldtrollen{/link} ums Überleben. Die Seuche hat bereits einige von ihnen gefunden.
• {b}Die Toten, die nicht ruhen.{/b} Geister wandeln in {link:darrowshire}Darrowshire{/link} und im {link:terrordale}Schreckenstal{/link}, und manche von ihnen warten noch immer darauf, dass die Lebenden heimkehren.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Seuche.{/b} Der {link:cult-of-the-damned}Kult der Verdammten{/link} verbreitete die Seuche des Untodes durch das Getreide Lordaerons. Die östlichen Dörfer aßen davon und starben, und dann erhoben sie sich.
• {b}Das Ausmerzen von Stratholme.{/b} Prinz {link:arthas-menethil}Arthas Menethil{/link} ließ Stratholme mit dem Schwert niedermachen, statt seine verseuchten Bewohner auferstehen zu lassen, und die Stadt brannte. Das {link:culling-of-stratholme}Ausmerzen von Stratholme{/link} ist in diesen Landen als der Tag in Erinnerung, an dem der Osten verloren ging.
• {b}Der Fall von Lordaeron.{/b} Nachdem der Prinz als Todesritter aus dem Norden zurückgekehrt war, fiel das Königreich. Beim {link:fall-of-lordaeron}Fall von Lordaeron{/link} wurden die östlichen Dörfer eines nach dem anderen überrannt. In {link:darrowshire}Darrowshire{/link} leisteten die Verteidiger einen Widerstand, an den die Annalen von Darrowshire noch heute erinnern.
• {b}Die Kriege der Toten.{/b} Die {link:scourge}Geißel{/link} machte den Osten zu ihrer Festung. Der Scharlachrote Kreuzzug erhob sich aus den Überlebenden und nahm {link:tyr-s-hand}Tyrs Hand{/link} ein. Die {link:argent-dawn}Argentumdämmerung{/link} sagte sich vom Kreuzzug los und fand ihre Heimat in der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Die Verlassenen kamen in den Osten, als {link:sylvanas-windrunner}die Bansheekönigin{/link} nach einem ihrer alten Waldläufer suchte.]=],
		},
		{
			title = "Überlieferungen der Pestländer",
			text = [=[• Die Leute der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} sagen, die kleine {link:pamela-redpath}Pamela Redpath{/link} warte noch immer in ihrem Haus südlich von {link:darrowshire}Darrowshire{/link}, und in stillen Nächten könne man hören, wie sie Reisende nach ihrer Puppe fragt.
• Wer durch das {link:terrordale}Schreckenstal{/link} kommt, erzählt von einem Händler dort, dessen Preise nach seinen eigenen Worten wahnsinnig sind. Man ist sich nicht sicher, dass das Wort nur eine Prahlerei ist.
• Die {link:argent-dawn}Argentumdämmerung{/link} zahlt in Tapferkeit für die Geißelsteine, die die Toten bei sich tragen. Ihre Rüstmeister führen sorgfältig Buch.
• Es heißt, der Streiter der Verlassenen in {link:the-marris-stead}Marris' Siedlung{/link} nenne jeden lebenden Diener, der zu ihm kommt, einen Schwachkopf, und das sei noch sein freundlichstes Wort.]=],
		},
	},
})

Translate("deDE", "light-s-hope-chapel", {
	title = "Kapelle des hoffnungsvollen Lichts",
	aliases = { "Hoffnungsvolles Licht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kapelle des hoffnungsvollen Lichts steht auf einer grünen Anhöhe im äußersten Osten der Pestländer, das einzige Stück reinen Bodens auf viele Meilen. Sie ist die Heimat der {link:argent-dawn}Argentumdämmerung{/link}. Um die alte Kapelle hat die Dämmerung Zelte, Schmieden und Ställe errichtet, und ihre Wachposten beobachten die Straßen Tag und Nacht. {link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link} hält im Inneren der Kapelle Rat. {link:duke-nicholas-zverenhoff}Herzog Nicholas Zverenhoff{/link}, {link:carlin-redpath}Carlin Redpath{/link}, der untote Ritter {link:leonid-barthalomew}Leonid Barthalomew{/link} und die Alchemistin {link:betina-bigglezink}Betina Bigglezink{/link} arbeiten unter ihren Mauern. Reisende aller Völker kommen hierher, denn die Dämmerung fragt nicht, wer ihre Verbündeten früher waren. Unterhalb der Anhöhe liegt eine Grube, in der die Dämmerung ihre Toten bettet, und selbst diese sind nicht vor Dieben sicher.]=],
		},
	},
})

Translate("deDE", "tyr-s-hand", {
	title = "Tyrs Hand",
	aliases = { "Die Scharlachrote Basilika" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tyrs Hand ist eine ummauerte Stadt an der südöstlichen Küste der Pestländer und die größte Festung des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} im Osten. Ihre Garnison untersteht {link:high-general-abbendis}Hochgeneral Abbendis{/link}, und die Scharlachrote Basilika erhebt sich in ihrem Herzen. Jeden Tag reitet ein Kurier zwischen Tyrs Hand und der Führung des Kreuzzugs im Norden, und jeden Tag schickt die Stadt ihre Soldaten gegen die {link:scourge}Geißel{/link}. Die Kreuzzügler trauen keinem Fremden. Wer ohne die Farben des Kreuzzugs an die Tore kommt, wird niedergemacht. Die Verlassenen, die am meisten unter den Händen des Kreuzzugs gelitten haben, beobachten die Stadt genau.]=],
		},
	},
})

Translate("deDE", "corin-s-crossing", {
	title = "Corins Kreuzung",
	aliases = { "Corins" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Corins Kreuzung war ein Dorf am Treffpunkt der alten Straßen in der Mitte der östlichen Marken. Nun ist es ein Nest des {link:cult-of-the-damned}Kults der Verdammten{/link}. Seine Häuser sind voller Kultisten und auferstandener Toter, und die {link:scourge}Geißel{/link} sammelt sich dort so dicht, dass {link:nathanos-blightcaller}Nathanos Blightcaller{/link} seine Diener dorthin schickt, um frisches Aas zu holen. Westlich des Dorfes öffnet sich eine tiefe Schlucht in der Erde. Die Annalen von {link:darrowshire}Darrowshire{/link} sagen, dass das Schwert von Marduk dem Schwarzen zerbrochen auf ihrem Grund liegt und dass der Leichnam von {link:horgus-the-ravager}Horgus{/link} dem Verwüster in einen See im Nordwesten geworfen wurde.]=],
		},
	},
})

Translate("deDE", "darrowshire", {
	title = "Darrowshire",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Darrowshire war ein Weiler in den südlichen Hügeln der östlichen Marken. Als die {link:scourge}Geißel{/link} kam, flohen seine Bewohner nicht. Unter {link:joseph-redpath}Hauptmann Joseph Redpath{/link} standen sie und kämpften, und dort starben sie. Die Annalen von Darrowshire verzeichnen, dass der Hauptmann selbst in der Schlacht verderbt wurde und sich gegen die Seinen wandte. Nun ist das Dorf eine Ruine, und seine Toten ruhen nicht. Geister wandeln über seinen Platz. Südlich der Ruinen steht das Haus der Redpaths, wo ein kleines Mädchen noch immer darauf wartet, dass sein Vater aus dem Kampf heimkehrt.]=],
		},
	},
})

Translate("deDE", "the-marris-stead", {
	title = "Marris' Siedlung",
	aliases = { "Marris-Siedlung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marris' Siedlung ist ein Hof im Südwesten der Pestländer, nahe der Grenze zu den westlichen Landen. Er war die Heimat von {link:nathanos-blightcaller}Nathanos Marris{/link}, einem Waldläuferlord Lordaerons. Als die {link:scourge}Geißel{/link} über die Gegend hinwegfegte, hielt Nathanos auf diesem Hof stand, und hier fiel er. Er ist als Diener der Bansheekönigin zu ihm zurückgekehrt. Nun lebt er dort mit seinen Hunden, und die Lebenden, die zum Hof kommen, sind entweder {link:forsaken}Verlassene{/link} im Auftrag der Dunklen Fürstin oder Soldaten der {link:alliance}Allianz{/link}, die ausgesandt wurden, um ihm ein Ende zu machen. Schädel liegen über die Felder verstreut.]=],
		},
	},
})

Translate("deDE", "terrordale", {
	title = "Schreckenstal",
	aliases = { "Terrorweb-Tunnel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Schreckenstal liegt im Nordwesten der Pestländer, wo das Land zur westlichen Grenze hin abfällt. Einst war es eine Stadt mit einem Gasthaus und einem Markt. Nun spukt es in seinen Straßen, und die Gruftbestien der {link:scourge}Geißel{/link} kriechen durch den langen Terrorweb-Tunnel, der es mit den westlichen Landen verbindet. Zwei seltsame Männer leben zwischen den Ruinen. {link:egan}Egan{/link} jagt Geister mit einem Gerät eigener Bauart. {link:augustus-the-touched}Augustus{/link}, den die Reisenden den Verrückten nennen, wartet darauf, seinen Laden wieder zu öffnen.]=],
		},
	},
})

Translate("deDE", "plaguewood", {
	title = "Der Pestwald",
	aliases = { "Geißelfeste" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Pestwald ist ein verseuchter Wald im Nordwesten, der sich um die Mauern von {red:stratholme}Stratholme{/red} ausbreitet. Er ist eine Werkstatt der {link:scourge}Geißel{/link}. Zikkurats und Schlachthäuser stehen zwischen den toten Bäumen, und die Geißel bewacht sie genau, denn die Toten ziehen Macht aus diesen Bauten und nähen in ihnen neue Schrecken zusammen. Die Ghule und Schinder, die durch den Wald streifen, waren einst die Leute der östlichen Dörfer. Die {link:argent-dawn}Argentumdämmerung{/link} hat einen Sprengmeister angeheuert, um die Bauten niederzureißen.]=],
		},
	},
})

Translate("deDE", "zul-mashar", {
	title = "Zul'Mashar",
	aliases = { "Mazra'Alor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zul'Mashar ist eine zerstörte Trollstadt im äußersten Nordosten der Pestländer, nahe den Grenzen von {link:quel-thalas}Quel'Thalas{/link}. Die {link:trolls}Trolle{/link} der Mossflayer halten sie unter Kriegsherr Thresh'jin und dem Hexendoktor Zul'Brin Warpbranch. Die Seuche hat auch sie gefunden. Einige ihrer Späher aßen auf dem Heimweg verseuchtes Fleisch, und die Stimme eines Lichs treibt sie nun, die Krankheit zu ihrem eigenen Volk zu tragen. Südwestlich der Stadt liegen die älteren Ruinen von Mazra'Alor.]=],
		},
	},
})

Translate("deDE", "the-noxious-glade", {
	title = "Das giftige Tal",
	aliases = { "Giftiges Tal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das giftige Tal ist ein vergiftetes Tal im Nordosten der Pestländer, nördlich der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Seine Luft ist dick und grün, und Schlämme aus lebendiger Fäulnis kriechen durch seine Senken. Die {link:scourge}Geißel{/link} hält hier ihre Streiter, und der {link:cult-of-the-damned}Kult der Verdammten{/link} vollzieht zwischen den Bäumen finstere Riten. Einige der Streiter, die durch {link:stranglethorn-vale}das Tal{/link} wandeln, kämpften in der Schlacht von {link:darrowshire}Darrowshire{/link}, und ihre Schädel hallen noch immer von der Erinnerung daran wider.]=],
		},
	},
})

Translate("deDE", "thondroril-river", {
	title = "Thondroril",
	aliases = { "Thondroril" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Thondroril ist der Fluss, der die östlichen Pestländer von den westlichen trennt. Seine Wasser sind dunkel und träge, und nur wenige Reisende verweilen an seinen Ufern. Doch am Ostufer, verborgen zwischen den Bäumen, steht eine kleine Hütte mit einer Angelschnur und einem Kochfeuer. Ein alter Mann lebt dort allein mit seinem Pferd Mirador. Sein Name ist {link:tirion-fordring}Tirion Fordring{/link}. Er war einst ein Lord und ein Paladin der Silbernen Hand, und er verlor beide Titel um eines {link:orcs}Orcs{/link} willen. Er bittet seine Gäste nur, mit den Hunden und den Fledermäusen zu helfen, und im Gegenzug bietet er eine warme Mahlzeit und die Geschichte seines Lebens.]=],
		},
	},
})

Translate("deDE", "crown-guard-tower", {
	title = "Turm der Kronenwache",
	aliases = { "Kronenwache" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Turm der Kronenwache ist ein alter Wachturm Lordaerons an der südlichen Straße, zwischen {link:darrowshire}Darrowshire{/link} und {link:the-marris-stead}Marris' Siedlung{/link}. Er wurde errichtet, um die Straßen des Königs im Osten zu bewachen. Der König ist tot, und die Straßen gehören der {link:scourge}Geißel{/link}, doch der Turm steht noch, ein einsamer steinerner Finger über der Verseuchung. Soldaten der Lebenden suchen manchmal in ihm Schutz. Keiner von ihnen bleibt lange.]=],
		},
	},
})

Translate("deDE", "quel-lithien-lodge", {
	title = "Quel'Lithien-Lodge",
	aliases = { "Quel'Lithien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Quel'Lithien-Lodge ist eine Jagdhütte der {link:high-elves}Hochelfen{/link} an der nördlichen Grenze der Pestländer, nahe der Straße nach {link:quel-thalas}Quel'Thalas{/link}. Waldläufer, Waldhüter und Pfadläufer halten hier unter {link:ranger-lord-hawkspear}Waldläuferlord Hawkspear{/link} Wache. Die Hütte bewahrt auch Aufzeichnungen aus den alten Tagen, als die Hochelfen die Waldläufer Lordaerons ausbildeten. Unter ihnen ist die Quel'Thalas-Registratur, die vom sterblichen Leben des {link:nathanos-blightcaller}Nathanos Marris{/link} erzählt. Der Blightcaller will sie zurück, und es kümmert ihn nicht, wie viele Elfen dafür leiden müssen.]=],
		},
	},
})

Translate("deDE", "the-undercroft", {
	title = "Das Tiefgewölbe",
	aliases = { "Tiefgewölbe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Tiefgewölbe ist eine alte Gruft im Südwesten der Pestländer, südlich von {link:the-marris-stead}Marris' Siedlung{/link}. Es war eine Ruhestätte für die Toten der östlichen Dörfer. Unter seinen Gräbern ist ein falsches. Als {link:tirion-fordring}Tirion Fordring{/link} verbannt wurde, erzählte man seinem Sohn, sein Vater sei gestorben, und der Junge wurde hierhergebracht, um zu trauern. Nun ist die Gruft das Versteck toter Trolldiebe unter {link:zaeldarr-the-outcast}Zaeldarr{/link} dem Ausgestoßenen, die nachts hinausschleichen, um Leichen aus der Grube an der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} zu stehlen. Hinter der Gruft, neben einem alten Wagen, vergrub ein Mossflayer eine Truhe, bevor die Seuche ihm den Verstand nahm.]=],
		},
	},
})

Translate("deDE", "northdale", {
	title = "Northdale",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Northdale war ein Weiler im Nordosten der Pestländer, jenseits der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Als die Silberne Hand zerbrochen wurde, leistete der junge Paladin {link:taelan-fordring}Taelan Fordring{/link} in Northdale einen letzten Widerstand, und dort warf er das Banner des Ordens nieder. Das Banner liegt noch zwischen den Ruinen. Westlich des Weilers, in den nördlichen Ödlanden, streift die große Made {link:borelgore}Borelgore{/link} umher, die ganze Soldatentrupps verschlungen hat.]=],
		},
	},
})

Translate("deDE", "the-fungal-vale", {
	title = "Das Fungustal",
	aliases = { "Fungustal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Fungustal ist ein abgesenktes Tal im Westen der Pestländer, wo riesige Pilze in der Fäulnis der Seuche wachsen. Die {link:scourge}Geißel{/link} hält hier ihre Streiter, wie sie es im giftigen Tal tut, und der {link:cult-of-the-damned}Kult der Verdammten{/link} hat zwischen den Pilzen ein Lager errichtet. Es ist auch das Revier der albinoweißen Dämonenfledermaus {link:duskwing}Duskwing{/link}, des einzigen Geschöpfs, das der {link:nathanos-blightcaller}Blightcaller{/link} offen hasst.]=],
		},
	},
})

Translate("deDE", "northpass-tower", {
	title = "Nordpassturm",
	aliases = { "Nordpass" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Nordpassturm bewacht die nördliche Straße aus den Pestländern hinaus, in Richtung der Pässe von {link:quel-thalas}Quel'Thalas{/link}. Er wurde gebaut, um die Grenze zwischen {link:humans}Menschen{/link} und Elfen zu beobachten, als diese Grenze noch eine freundliche war. Nahe dem Turm lebt die Hochelfe {link:aurora-skycaller}Aurora Skycaller{/link}, eine Hüterin alter elfischer Überlieferung, die um die Fehler ihrer Vorfahren trauert. Nur wenige kommen zu ihr, und noch weniger kommen mit einer Frage, die sie zu beantworten bereit ist.]=],
		},
	},
})

Translate("deDE", "nathanos-blightcaller", {
	title = "Nathanos Blightcaller",
	subtitle = "Streiter der Bansheekönigin",
	found = "Marris' Siedlung, im Südwesten der Pestländer",
	hint = [=[Suche den Waldläufer der Verlassenen, der im Südwesten einen Hof voller Schädel und Hunde hält.]=],
	allegiance = "Verlassene · Sylvanas Windrunner",
	aliases = { "Nathanos", "Nathanos Marris", "Blightcaller" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nathanos Blightcaller ist der Streiter der {link:forsaken}Verlassenen{/link} in den Östlichen Pestländern. Im Leben war er Nathanos Marris, ein Waldläuferlord von {link:lordaeron}Lordaeron{/link} und der einzige Mensch, dem je erlaubt wurde, unter den Waldläufern von {link:quel-thalas}Quel'Thalas{/link} ausgebildet zu werden. Er fiel auf seinem eigenen Hof der {link:scourge}Geißel{/link} zum Opfer und erhob sich als ihr Sklave. {link:sylvanas-windrunner}Sylvanas Windrunner{/link} befreite ihn. Nun hält er mit seinen Seuchenhunden {link:the-marris-stead}Marris' Siedlung{/link}, und er jagt die Geißel und die Lebenden mit demselben kalten Hass. Er ist grausam zu denen, die ihm dienen, und er vertraut niemandem außer der Dunklen Fürstin.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nathanos ist zweierlei zugleich, und beide Seiten des Krieges wissen es. Für die {link:alliance}Allianz{/link} war er ein Held. Sein Können errang Siege in einem Jahrzehnt des Krieges, und kein anderer Mensch stieg je in den Rang eines Waldläuferlords auf. Für die Verlassenen ist er der erste und gefürchtetste der Streiter der Bansheekönigin. Sein Schicksal ist eine Wunde für die Allianz. Der Regent in {link:stormwind-city}Stormwind{/link} erfuhr davon und sandte ein Heer aus, um ihm ein Ende zu machen.]=],
		},
		{
			title = "Leben und Tod",
			text = [=[Nathanos wurde in {link:lordaeron}Lordaeron{/link} als Mensch geboren. Die {link:high-elves}Hochelfen{/link} nahmen ihn in ihren Waldläuferorden auf, was sie für keinen anderen seines Volkes je getan hatten, und er stieg in dessen höchsten Rang auf. Als die {link:scourge}Geißel{/link} über die östlichen Marken hinwegfegte, hielt er auf seinem Hof zur Verteidigung des Königreichs stand. Eine gewaltige Welle von Toten überwältigte ihn. Das Letzte, was er sah, war eine Monstrosität, die über ihm schwebte, die Eingeweide aus der Brust hängend. Er erwachte als einer der Geißel, sein Geist an den des Lichkönigs gebunden. Lange Zeit war er hilflos. Dann kam {link:sylvanas-windrunner}die Bansheekönigin{/link} zu ihm, wie er es irgendwie gewusst hatte, und brach seine Ketten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er jagte die Monstrosität Ramstein nach seiner Befreiung monatelang durch die Ödlande, bis sie nach Stratholme floh.
• Er bildet die Verlassenen aus, die {link:sylvanas-windrunner}die Dunkle Fürstin{/link} ihm schickt, mit Verachtung und ohne Gnade.
• Er erschlug die Agenten von {link:si-7}SI:7{/link}, die {link:stormwind-city}Stormwind{/link} ausgesandt hatte, um zu erfahren, wer der Blightcaller war.
• Er schmiedet auf Befehl von {link:varimathras}Varimathras{/link} Pläne gegen den Scharlachroten Kreuzzug.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Nathanos hält {link:the-marris-stead}Marris' Siedlung{/link} allein mit seinen Hunden. Er schickt seine Diener aus, um die Hunde mit Fäulnis aus {link:corin-s-crossing}Corins Kreuzung{/link} zu füttern, die Seuchenfledermäuse von seinem Himmel zu vertreiben und die Ungeheuer des Nordens zu jagen. Die Verlassenen, die seine Ausbildung überleben, verdienen sich einen Platz unter seinen Streitern. Die Soldaten der {link:alliance}Allianz{/link}, die zur Siedlung kommen, verlassen sie für gewöhnlich nicht wieder.]=],
		},
	},
	chapters = {
		{
			title = "Der Streiter der Bansheekönigin",
			hint = [=[Folge dem Ruf der Dunklen Fürstin und melde dich in Marris' Siedlung.]=],
			text = [=[Die Bansheekönigin schickt ihre erfahrensten Diener nach Osten zu {link:the-marris-stead}Marris' Siedlung{/link}. Nathanos empfängt sie mit Hohn. Er nimmt an, sie seien gekommen, um seine Hunde zu füttern, denn er kann sich keinen anderen Grund vorstellen, weshalb sie ihn behelligen sollten.]=],
		},
		{
			title = "Töten mit Absicht",
			hint = "Verdiene dir deinen Unterhalt in Marris' Siedlung.",
			text = [=[Nathanos' erste Lektionen sind Botengänge. Seine Diener zermahlen die Fäulnis frisch erschlagener {link:scourge}Geißel{/link} zu Futter für seine Hunde, und sie jagen die Seuchenfledermäuse, die ihn belästigen, sobald er den Hof verlässt. Er nennt dies Ausbildung. Er sagt auch, er habe Besseres zu tun, als Fledermäuse zu töten, und seine Diener nicht.]=],
		},
		{
			title = "Das Geheiß des Waldläuferlords",
			hint = [=[Birg bei den Elfen des Nordens eine Aufzeichnung über das sterbliche Leben des Blightcallers.]=],
			text = [=[In der {link:quel-lithien-lodge}Quel'Lithien-Lodge{/link} bewahrten die {link:high-elves}Hochelfen{/link} eine Registratur seines Lebens als Sterblicher. Nathanos wollte sie zurück, und er wollte, dass die Elfen, die sie hüteten, litten. Er sagte nicht, warum. Er warnte nur, keiner seiner Diener solle so töricht sein, sie zu lesen.]=],
		},
		{
			title = "Ramstein",
			hint = "Räche den Tod des Blightcallers.",
			text = [=[Es war die Monstrosität Ramstein, die über Nathanos schwebte, als er starb. Nachdem {link:sylvanas-windrunner}Sylvanas{/link} ihn befreit hatte, jagte er sie monatelang, bis sie nach Stratholme floh. Als ihm ihr Kopf gebracht wurde, fragte er laut, ob sie gebettelt habe und ob sie überhaupt wissen könne, was Gnade sei. Er schwor, den Kopf an seine Wand zu hängen.]=],
		},
		{
			title = "Das Scharlachrote Orakel",
			hint = [=[Führe die List des Blightcallers gegen den Scharlachroten Kreuzzug aus.]=],
			text = [=[{link:varimathras}Varimathras{/link} ließ ausrichten, dass der Großkreuzzügler des Scharlachroten Kreuzzugs getroffen werden müsse. Nathanos fand die Schwäche im täglichen Kurier des Kreuzzugs. Er schrieb die Befehle des Großkreuzzüglers um und schickte einen als Kreuzzügler verkleideten Diener nach {link:tyr-s-hand}Tyrs Hand{/link}. Die Befehle verlangten, dass das Scharlachrote Orakel, {link:demetria}Demetria{/link}, die oberste Ratgeberin des Großkreuzzüglers, nach Norden nach Stratholme geschickt werde. Der Kreuzzug gehorchte. Nathanos wartete auf der Straße.]=],
		},
		{
			title = "Der Blightcaller enttarnt",
			hint = [=[Finde im Auftrag von Stormwind heraus, wer der Blightcaller ist.]=],
			text = [=[Drei Agenten von {link:si-7}SI:7{/link} gingen in die Östlichen Pestländer, um zu erfahren, wer der Blightcaller war, und keiner kam zurück. Ihre Abzeichen wurden nahe {link:the-marris-stead}Marris' Siedlung{/link} gefunden. Als die Wahrheit ans Licht kam, brach sie denen das Herz, die Nathanos Marris gekannt hatten. Der Regent von {link:stormwind-city}Stormwind{/link} konnte nicht glauben, dass der Waldläuferlord zum Streiter der Bansheekönigin geworden war, und er rief nach einem Heer, um ihm ein Ende zu machen.]=],
		},
	},
	mentions = {
		{ text = "Der Streiter der Bansheekönigin" },
		{ text = "Töten mit Absicht" },
		{ text = "Die kleinen Ärgernisse des Unlebens" },
		{ text = "Das Geheiß des Waldläuferlords" },
		{ text = "{link:duskwing}Duskwing{/link}, oh wie ich dich hasse..." },
		{ text = "{link:borelgore}Der Beleibte{/link}" },
		{ text = "Ramstein" },
		{ text = "Der Ruf zum Kommando" },
		{ text = "Der purpurrote Kurier" },
		{ text = "Nathanos' List" },
		{ text = "Rückkehr zu Nathanos" },
		{ text = "{link:demetria}Das Scharlachrote Orakel{/link}, Demetria" },
		{ text = "Die {link:eastern-plaguelands}Östliche Pest{/link}" },
		{ text = "Der Blightcaller kommt" },
		{ text = "Die Ordnung muss wiederhergestellt werden" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "befreite ihn vom Lichkönig" },
		{ id = "varimathras", name = "Varimathras", note = "schickt ihm Befehle aus Undercity" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "fordert seinen Tod" },
		{ id = "ranger-lord-hawkspear", name = "Waldläuferlord Hawkspear", note = "bewahrt die Registratur seines sterblichen Lebens" },
		{ id = "duskwing", name = "Duskwing", note = "die Fledermaus, die er hasst" },
		{ id = "borelgore", name = "Borelgore", note = "kostete ihn ganze Regimenter" },
		{ id = "demetria", name = "Demetria", note = "das Orakel, das er jagte" },
	},
})

Translate("deDE", "lord-maxwell-tyrosus", {
	title = "Lord Maxwell Tyrosus",
	subtitle = "Anführer der Argentumdämmerung",
	found = "Im Inneren der Kapelle des hoffnungsvollen Lichts",
	hint = [=[Suche den Lord, der im Inneren der Kapelle des hoffnungsvollen Lichts Rat hält.]=],
	allegiance = "Argentumdämmerung",
	aliases = { "Maxwell Tyrosus", "Tyrosus", "Lord Maxwell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Maxwell Tyrosus führt die {link:argent-dawn}Argentumdämmerung{/link} vom Inneren der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} aus. Einst gehörte er dem {link:scarlet-crusade}Scharlachroten Kreuzzug{/link} an. Als er sah, wohin dessen Eifer führte, weigerte er sich zu folgen, und er half, einen Orden zu gründen, der die {link:scourge}Geißel{/link} bekämpfen sollte, ohne alle anderen zu hassen. Er verlässt die Kapelle selten, und seit Jahren hat er Außenstehenden keine Audienz gewährt. Wer vor ihn gebracht wird, hat es sich verdient.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tyrosus ist das Herz des großen Wagnisses der Dämmerung: eines Ordens, der niemanden fragt, welchem Volk oder Banner er gedient hat, sondern nur, ob er gegen die Toten stehen will. Um ihn versammeln sich ein untoter Ritter, eine gnomische Alchemistin, ein adliger Sprachgelehrter und ein trauernder Sohn von {link:darrowshire}Darrowshire{/link}. Dass sie überhaupt zusammenarbeiten, ist sein Werk.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verließ den Scharlachroten Kreuzzug und half, die {link:argent-dawn}Argentumdämmerung{/link} zu gründen.
• Er führt die Dämmerung von der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} aus in ihrem Krieg gegen die {link:scourge}Geißel{/link}.
• Er hütet den Argentumhort, der seit Jahren verschlossen ist.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken sagen wenig über Tyrosus' Leben vor dem Kreuzzug, noch über die Lande hinter seinem Titel. Dieser Eintrag verzeichnet nur seinen Platz in der Dämmerung.]=],
		},
	},
	chapters = {
		{
			title = "Eine Audienz bei Lord Maxwell",
			hint = [=[Beweise dich als Streiter der Dämmerung und lass dich vor ihren Anführer bringen.]=],
			text = [=[{link:duke-nicholas-zverenhoff}Herzog Nicholas Zverenhoff{/link} brachte den Streiter vor Lord Maxwell selbst, eine Ehre, die die Dämmerung seit Jahren keinem Außenstehenden gewährt hatte. Tyrosus empfing den Neuankömmling als würdigen Verbündeten. Zum ersten Mal seit vielen Jahren wurde der Argentumhort einer Hand von außerhalb des Ordens geöffnet.]=],
		},
	},
	mentions = {
		{ text = "Lord Maxwell Tyrosus" },
		{ text = "Der Argentumhort" },
	},
	bonds = {
		{ id = "duke-nicholas-zverenhoff", name = "Herzog Nicholas Zverenhoff", note = "bringt ihm Streiter" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "ein untoter Ritter seines Ordens" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "ein Bruder der Dämmerung" },
	},
})

Translate("deDE", "duke-nicholas-zverenhoff", {
	title = "Herzog Nicholas Zverenhoff",
	subtitle = "Herzog der Argentumdämmerung",
	found = [=[Kapelle des hoffnungsvollen Lichts, unter den Mauern der Kapelle]=],
	hint = [=[Sprich mit dem Herzog, der in der Kapelle des hoffnungsvollen Lichts die Aufträge der Dämmerung vergibt.]=],
	allegiance = "Argentumdämmerung",
	aliases = { "Zverenhoff", "Nicholas Zverenhoff", "Der Herzog" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Herzog Nicholas Zverenhoff ist einer der angesehensten Anführer der {link:argent-dawn}Argentumdämmerung{/link}. Er ist ein Adliger und ein gelehrter Mann, im ganzen Orden als brillanter Sprachgelehrter bekannt. In der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link} vergibt er den Auftrag der Dämmerung an alle, die für sie kämpfen wollen, und er bezahlt für jeden Geißelstein, der den Toten abgenommen wird. Er ist gütig zu seinen Verbündeten und gänzlich ohne Gnade gegenüber der {link:scourge}Geißel{/link} und den Eiferern des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Herzog ist der Anwerber der Dämmerung und ihr Richter über Streiter. Er glaubt, dass alles, was bis zum Äußersten getrieben wird, eine Gefahr für die Welt ist, und er zählt den blinden Eifer des Kreuzzugs zu diesen Gefahren. Er lehrt, dass die Dämmerung duldsam und doch unbeugsam in ihren Überzeugungen sein muss. Wen er für würdig befindet, den bringt er vor {link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er vergibt den Auftrag der {link:argent-dawn}Argentumdämmerung{/link}, der es seinen Trägern erlaubt, Geißelsteine von den Gefallenen zu sammeln.
• Er tauscht Geißelsteine gegen die Zeichen der Tapferkeit der Dämmerung.
• Er studiert seltsame Schriften, die der Dämmerung geschickt werden, etwa das Buch eines Geistsprechers aus {link:winterspring}Winterspring{/link}.
• Er schickt Streiter nach Stratholme, gegen den Kreuzzug ebenso wie gegen die {link:scourge}Geißel{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, wo die Ländereien des Herzogs vor der Seuche lagen oder wie er zur Dämmerung kam.]=],
		},
	},
	chapters = {
		{
			title = "Der Auftrag der Dämmerung",
			hint = [=[Nimm in der Kapelle des hoffnungsvollen Lichts den Auftrag der Dämmerung an.]=],
			text = [=[Jeder Soldat, der im Namen der Dämmerung gegen die {link:scourge}Geißel{/link} kämpft, trägt ihren Auftrag. Mit ihm, erklärte der Herzog, darf der Träger die Geißelsteine nehmen, die die Toten manchmal bei sich tragen, ihre Rangzeichen. Der Herzog zahlt für jeden Satz, und am besten zahlt er für die Steine der Oberherren der Geißel.]=],
		},
		{
			title = "Der Archivar",
			hint = [=[Schlage in Stratholme gegen die Aufzeichnungen des Scharlachroten Kreuzzugs zu.]=],
			text = [=[Der Herzog fragte, wie viele Unschuldige der Kreuzzug im Namen des Lichts vernichtet habe. Er wollte seinen Archivar in Stratholme erschlagen und das Scharlachrote Archiv verbrannt sehen. Als die Tat vollbracht war, frohlockte er: Jahre an Wissen des Kreuzzugs waren in Rauch aufgegangen.]=],
		},
		{
			title = "Die Wahrheit bricht herein",
			hint = [=[Bring dem Herzog den Beweis dafür, was den Scharlachroten Kreuzzug wirklich befehligt.]=],
			text = [=[Der Kopf, der vor den Herzog gelegt wurde, war nicht der eines {link:humans}Menschen{/link}. Der Großkreuzzügler des Scharlachroten Kreuzzugs war ein Schreckenslord, Balnazzar, Bruder jenes {link:varimathras}Varimathras{/link}, der in {link:undercity}Undercity{/link} dient. Zverenhoff konnte sich nur fragen, wie lange der Kreuzzug einem Dämon gedient hatte, ohne es zu wissen.]=],
		},
		{
			title = "Über alle Erwartungen",
			hint = [=[Vernichte den Herrn von Stratholme und beweise dich als Streiter des Herzogs.]=],
			text = [=[Zuletzt verlangte der Herzog den Kopf von Baron Rivendare, den er Kel'Thuzads Laufburschen nannte. Wer ihn brachte, wurde sein Streiter, der erste seit vielen Jahren, und der erste Außenstehende seit Jahren, der vor {link:lord-maxwell-tyrosus}Lord Maxwell{/link} gebracht wurde.]=],
		},
	},
	mentions = {
		{ text = "Auftrag der {link:argent-dawn}Argentumdämmerung{/link}" },
		{ text = "Geißelsteine der Diener" },
		{ text = "Geißelsteine der Eindringlinge" },
		{ text = "Geißelsteine der Verderber" },
		{ text = "Herzog Nicholas Zverenhoff" },
		{ text = "Der Archivar" },
		{ text = "Die Wahrheit bricht herein" },
		{ text = "Über alle Erwartungen" },
		{ text = "{link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link}" },
	},
	bonds = {
		{ id = "lord-maxwell-tyrosus", name = "Lord Maxwell Tyrosus", note = "der Anführer, dem er dient" },
		{ id = "betina-bigglezink", name = "Betina Bigglezink", note = "arbeitet an seiner Seite" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "arbeitet an seiner Seite" },
	},
})

Translate("deDE", "carlin-redpath", {
	title = "Carlin Redpath",
	subtitle = "Überlebender von Darrowshire",
	found = "Kapelle des hoffnungsvollen Lichts",
	hint = [=[Suche den trauernden Mann aus Darrowshire, der der Dämmerung in der Kapelle des hoffnungsvollen Lichts dient.]=],
	allegiance = "Argentumdämmerung",
	aliases = { "Carlin", "Bruder Carlin", "Onkel Carlin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Carlin Redpath ist ein Soldat der {link:argent-dawn}Argentumdämmerung{/link} in der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Er wurde in {link:darrowshire}Darrowshire{/link} geboren, und er ist einer der sehr wenigen, die die Schlacht überlebten, die es zerstörte. Sein Bruder war {link:joseph-redpath}Hauptmann Joseph Redpath{/link}, der die Verteidigung des Dorfes anführte. Seine kleine Nichte {link:pamela-redpath}Pamela{/link} ist tot. Carlin hat seine Trauer in ein einziges Ziel verwandelt: Rache an der {link:scourge}Geißel{/link}, die ihm seine Heimat nahm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Carlin ist die lebendige Erinnerung an {link:darrowshire}Darrowshire{/link}. Seine Helden, seine Schurken und seine Toten rufen in seinen Träumen nach ihm. Als man ihm die Annalen von Darrowshire brachte, erfuhr er, dass er vielleicht mehr für sie tun konnte, als zu trauern.]=],
		},
		{
			title = "Taten",
			text = [=[• Er überlebte die Schlacht von {link:darrowshire}Darrowshire{/link} und den Verrat seines Bruders.
• Er dient der {link:argent-dawn}Argentumdämmerung{/link} in der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}.
• Er sammelte die Reliquien der Schlacht von Darrowshire, damit das Schicksal des Dorfes verändert werden könne.]=],
		},
	},
	chapters = {
		{
			title = "Onkel Carlin",
			hint = [=[Bring Carlin Nachricht von dem kleinen Mädchen, das noch immer in Darrowshire wartet.]=],
			text = [=[Carlin hatte geglaubt, {link:pamela-redpath}Pamela{/link} könnte noch leben. Als er erfuhr, dass sie tot war und noch immer als Geist wartete, rief er aus, er würde sofort mit ihr tauschen. Dann legte er seine Trauer beiseite und bat darum, die gequälten Geister der Verteidiger Darrowshires von der {link:scourge}Geißel{/link} zu befreien, denn viele von ihnen dienen ihr nun als Ghule und Schinder.]=],
		},
		{
			title = "Die Annalen von Darrowshire",
			hint = [=[Bring die Erweiterten Annalen von Darrowshire zur Kapelle des hoffnungsvollen Lichts.]=],
			text = [=[Eine seltsame Gnomin in {link:ruins-of-andorhal}Andorhal{/link} hatte ihre Magie an den Annalen von {link:darrowshire}Darrowshire{/link} gewirkt, und neue Seiten waren am Ende des Buches erschienen. Sie erzählten von den Tagen nach der Schlacht, und eine von ihnen sprach von Carlin selbst. Er las sie und konnte nicht sagen, ob sie wahr waren. Er beschloss, es herauszufinden.]=],
		},
		{
			title = "Helden und Schurken",
			hint = [=[Sammle die Reliquien der Helden und Schurken von Darrowshire.]=],
			text = [=[Die Annalen nannten sie alle. Das Libram des Paladins {link:davil-lightfire}Davil Lightfire{/link} war nach {link:hearthglen}Hearthglen{/link} gebracht worden. Der gesprungene Schild von {link:joseph-redpath}Hauptmann Redpath{/link} lag nahe einer Scheune im Westen. Der Schädel des Ghulfürsten {link:horgus-the-ravager}Horgus{/link} lag in einem See und das zerbrochene Schwert von Marduk dem Schwarzen in einer Schlucht nahe {link:corin-s-crossing}Corins Kreuzung{/link}. Zuletzt kamen die Schädel von Streitern der {link:scourge}Geißel{/link}, die in der Schlacht gekämpft hatten. Carlin verstand nicht ganz, warum diese Reliquien von Bedeutung waren. Er spürte nur, dass sie an seine Heimat gebunden waren.]=],
		},
		{
			title = "Rückkehr zu Chromie",
			hint = [=[Schicke die Reliquien von Darrowshire zu der Gnomin in Andorhal.]=],
			text = [=[Als alle Reliquien gesammelt waren, schickte Carlin sie nach Westen zu der Gnomin {link:chromie}Chromie{/link} im zerstörten Gasthaus von {link:ruins-of-andorhal}Andorhal{/link}. Sie hatte ihm etwas gesagt, was er kaum zu glauben wagte: dass {link:darrowshire}Darrowshire{/link} gerettet werden könne.]=],
		},
	},
	mentions = {
		{ text = "Onkel Carlin" },
		{ text = "Verteidiger von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Bruder Carlin" },
		{ text = "Helden von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Schurken von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Marodeure von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Rückkehr zu {link:chromie}Chromie{/link}" },
	},
	bonds = {
