Translate("deDE", "pamela-redpath", {
	title = "Pamela Redpath",
	subtitle = "Das Kind von Darrowshire",
	found = "Das Haus ihrer Familie, südlich der Ruinen von Darrowshire",
	hint = [=[Suche das kleine Mädchen, das in einem Haus südlich von Darrowshire wartet.]=],
	allegiance = "Darrowshire",
	aliases = { "Pamela", "Die kleine Pamela" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Pamela Redpath ist der Geist eines kleinen Mädchens aus {link:darrowshire}Darrowshire{/link}. Als die {link:scourge}Geißel{/link} kam, zog ihr Vater, {link:joseph-redpath}Hauptmann Joseph Redpath{/link}, in den Kampf, und ihre Tante {link:marlene-redpath}Marlene{/link} sagte ihr, sie solle im Haus bleiben und sich verstecken. Seitdem wartet sie dort. Sie weiß nicht, dass sie tot ist. Sie weiß nicht, was aus ihrem Vater wurde. Sie weiß nur, dass er nicht gekommen ist, um sie zu holen, dass böse Stimmen ihr manchmal im Dunkeln zuflüstern und dass sie ihre Puppe im Dorf gelassen hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Pamela ist der traurigste der Geister der Pestländer und derjenige, der die meisten Herzen bewegt hat. Ihre Tante, ihr Onkel und ihre Schwester baten jeweils Fremde, sie zu finden. Durch sie kommt die Geschichte von {link:darrowshire}Darrowshire{/link} und den Redpaths wieder ans Licht.]=],
		},
		{
			title = "Ihre Familie",
			text = [=[Ihr Vater war {link:joseph-redpath}Hauptmann Joseph Redpath{/link}, der die Verteidigung von {link:darrowshire}Darrowshire{/link} anführte. Ihre Tante {link:marlene-redpath}Marlene{/link} versteckte sie, als die Schlacht begann, und wandert nun als Geist nahe {link:ruins-of-andorhal}Andorhal{/link} umher. Ihr {link:carlin-redpath}Onkel Carlin{/link} dient der {link:argent-dawn}Argentumdämmerung{/link} in der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Ihre ältere Schwester {link:jessica-redpath}Jessica{/link} floh vor der Seuche aus {link:lordaeron}Lordaeron{/link} und lebt weit fort in {link:winterspring}Winterspring{/link}. Pamela erinnert sich, dass Jessica weinte, als sie ging, und versteht nicht, warum.]=],
		},
	},
	chapters = {
		{
			title = "Die kleine Pamela",
			hint = "Finde das Kind, das seine Verwandten gesucht haben.",
			text = [=[Pamela begrüßte ihren Besucher und fragte nach seinem Namen. Sie sprach von ihrem Vater, dem tapfersten Mann der ganzen Welt, und von ihrer Schwester {link:jessica-redpath}Jessica{/link}, die sich immer mit ihr versteckt hatte, um ihren Vater zu überraschen, wenn er heimkam.]=],
		},
		{
			title = "Pamelas Puppe",
			hint = "Finde die Puppe, die Pamela im Dorf gelassen hat.",
			text = [=[Die Puppe lag irgendwo in den Ruinen von {link:darrowshire}Darrowshire{/link}, wo die Toten noch wandeln. Als sie gefunden und zurückgebracht wurde, war Pamela überglücklich. Es war das Erste seit sehr langer Zeit, das sie tröstete.]=],
		},
		{
			title = "Die Schlacht von Darrowshire",
			hint = [=[Nimm an der Schlacht von Darrowshire teil und bring einen Vater heim.]=],
			text = [=[Mit dem Zauber der Gnomin {link:chromie}Chromie{/link} wurde die Schlacht von {link:darrowshire}Darrowshire{/link} unter ihren Geistern erneut geschlagen. Diesmal wurde {link:joseph-redpath}Hauptmann Redpath{/link} gerettet. Als die Kämpfe endeten, hörte Pamela ihren Vater ihr zuflüstern. Er sagte ihr, er habe die Geister vertrieben und komme nach Hause. Sie kochte Tee, mit sehr viel Zucker, für den, der ihm geholfen hatte. Dann gab sie diesem Freund einen Schlüssel ihres Vaters, der eine hinter dem Haus versteckte Truhe öffnete.]=],
		},
	},
	mentions = {
		{ text = "Schwester Pamela" },
		{ text = "Die kleine Pamela" },
		{ text = "Pamelas Puppe" },
		{ text = "Tante {link:marlene-redpath}Marlene{/link}" },
		{ text = "{link:carlin-redpath}Onkel Carlin{/link}" },
		{ text = "Die Schlacht von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Verborgene Schätze" },
	},
	bonds = {
		{ id = "joseph-redpath", name = "Joseph Redpath", note = "ihr Vater" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "ihr Onkel" },
		{ id = "marlene-redpath", name = "Marlene Redpath", note = "ihre Tante, die sie versteckte" },
		{ id = "jessica-redpath", name = "Jessica Redpath", note = "ihre ältere Schwester" },
	},
})

Translate("deDE", "joseph-redpath", {
	title = "Joseph Redpath",
	subtitle = "Hauptmann von Darrowshire",
	found = [=[Darrowshire, wenn sich seine Toten erheben, um erneut zu kämpfen]=],
	hint = [=[Steh den Toten von Darrowshire bei, wenn ihre Schlacht erneut geschlagen wird.]=],
	allegiance = "Darrowshire",
	aliases = { "Hauptmann Redpath", "Hauptmann Joseph Redpath", "Redpath der Verderbte" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Joseph Redpath führte die Verteidiger von {link:darrowshire}Darrowshire{/link} an, als die {link:scourge}Geißel{/link} kam. Er war Pamelas Vater und der Bruder von {link:carlin-redpath}Carlin{/link} und {link:marlene-redpath}Marlene{/link}. Die Annalen von Darrowshire sagen, dass er während der Schlacht verderbt wurde, sich den Reihen der Geißel anschloss und sich gegen sein eigenes Volk wandte. Sein Leichnam wurde zertrampelt und ging vor langer Zeit verloren. Nur sein Ehering blieb, vergraben unter seinem Denkmal nahe {link:ruins-of-andorhal}Andorhal{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Josephs Fall ist die Wunde im Herzen der Redpaths. {link:marlene-redpath}Marlene{/link} brachte es nicht über sich, {link:pamela-redpath}Pamela{/link} zu sagen, was aus ihm geworden war. Als die Schlacht durch Chromies Zauber noch einmal geschlagen wurde, verfiel er erneut der Verderbnis und wurde besiegt, und endlich wurde sein Geist gerettet.]=],
		},
	},
	mentions = {
		{ text = "Eine seltsame Historikerin" },
		{ text = "Die Annalen von {link:darrowshire}Darrowshire{/link}" },
		{ text = "Die Schlacht von {link:darrowshire}Darrowshire{/link}" },
	},
	bonds = {
		{ id = "pamela-redpath", name = "Pamela Redpath", note = "seine Tochter" },
		{ id = "carlin-redpath", name = "Carlin Redpath", note = "sein Bruder" },
		{ id = "davil-lightfire", name = "Davil Lightfire", note = "kämpfte an seiner Seite" },
	},
})

