			title = "Zusammenfassung",
			text = [=[Aurora Skycaller ist eine Hochelfe, die nahe dem {link:northpass-tower}Nordpassturm{/link} lebt. Sie spricht nicht gern über die Geschichte ihres Volkes, denn es schmerzt sie, dass die Fehler ihrer Vorfahren nie ungeschehen gemacht werden können. Doch als ein {link:dwarves}Zwerg{/link} der {link:explorers-league}Forscherliga{/link} ihr die Bruchstücke einer zerschmetterten Reliquie vom {link:lake-kel-theril}Kel'Therilsee{/link} in {link:winterspring}Winterspring{/link} schickte, erkannte sie darin den {link:crystal-of-zin-malor}Kristall von Zin-Malor{/link}, der große arkane Kräfte fassen und beherrschen konnte. Mit den heiligen Schriften der Hochgeborenen und den richtigen Reagenzien machte sie ihn wieder ganz, damit er den verfluchten Geistern gezeigt werden konnte, die ihn vor langer Zeit gestohlen hatten.]=],
		},
	},
	mentions = {
		{ text = "Gequälte Geister von {link:lake-kel-theril}Kel'Theril{/link}" },
		{ text = "Bruchstücke der Vergangenheit" },
		{ text = "Bruchstücke der Vergangenheit" },
		{ text = "Von der Vergangenheit gequält" },
	},
})

