Translate("deDE", "infiltrator-hameya", {
	title = "Infiltrator Hameya",
	subtitle = "Der infizierte Mossflayer",
	found = "Nahe Zul'Mashar",
	hint = [=[Finde den Troll, der um den Tod flehte, bevor die Seuche ihm den Willen nahm.]=],
	allegiance = "Geißel",
	aliases = { "Hameya" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hameya war ein Troll der Mossflayer. Auf der Straße nach {link:zul-mashar}Zul'Mashar{/link} aßen er und seine Gefährten verdorbenes Fleisch, und es veränderte sie. Hameya spürte die Worte eines Lichs in seinem Geist, die ihn drängten, heimzukehren und sein Volk zu infizieren. Bevor sein Wille ihn verließ, schrieb er eine Schriftrolle, die jeden, der sie fand, anflehte, ihn zu töten. Er hatte neben einem Wagen hinter dem {link:the-undercroft}Tiefgewölbe{/link} eine Truhe vergraben, und er trug ihren einzigen Schlüssel. Nun nennt die {link:scourge}Geißel{/link} ihn einen Infiltrator, und er geht auf sein eigenes Volk zu.]=],
		},
	},
	mentions = {
		{ text = "Hameyas Flehen" },
	},
})

